def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for a >= 1, b >= 2."""
    if n < 4:
        return 1 if n >= 1 else 0

    max_exp = n.bit_length() - 1
    primes = [p for p in range(2, max_exp + 1)
              if all(p % d for d in range(2, int(p ** 0.5) + 1))]

    def integer_root(value: int, exponent: int) -> int:
        lo = 1
        hi = 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** exponent <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    total = 0

    def visit(start: int, exponent: int, sign: int) -> None:
        nonlocal total
        total += sign * (integer_root(n, exponent) - 1)
        for i in range(start, len(primes)):
            p = primes[i]
            if exponent * p > max_exp:
                break
            visit(i + 1, exponent * p, -sign)

    visit(0, 1, 1)
    return total + 1

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.
    """
    def prefix(x: int) -> int:
        if x <= 0:
            return 0
        digits = list(map(int, str(x)))
        n = len(digits)

        # Every number containing a zero has digit product zero and is beautiful.
        # Count the remaining, zero-free numbers by their digit sum.
        zero_free_beautiful = 0
        for length in range(1, n + 1):
            if length < n:
                bound = [9] * length
            else:
                bound = digits

            for target_sum in range(1, 9 * length + 1):
                @lru_cache(None)
                def visit(pos: int, remaining: int, residue: int, tight: bool) -> int:
                    if pos == length:
                        return int(remaining == 0 and residue == 0)
                    limit = bound[pos] if tight else 9
                    total = 0
                    for d in range(1, min(9, limit) + 1):
                        if d > remaining:
                            continue
                        total += visit(
                            pos + 1,
                            remaining - d,
                            (residue * d) % target_sum,
                            tight and d == limit,
                        )
                    return total

                # Product is initialized to 1; all digits are nonzero.
                zero_free_beautiful += visit(0, target_sum, 1 % target_sum, True)

        return x - zero_free_beautiful

    return prefix(r) - prefix(l - 1)

MOD = 998244353

def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences lexicographically not greater than a, modulo 998244353."""
    # Precompute factorials for binomial coefficients up to 2*n.
    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top or top < 0:
            return 0
        return fact[top] * invfact[bottom] % MOD * invfact[top - bottom] % MOD

    def tail(m: int, lower: int) -> int:
        # Sum of completions over lower <= s <= m, where m nodes fill s slots.
        if m <= 0 or lower > m:
            return 0
        lower = max(lower, 1)
        # Lagrange inversion on T^lower / (1-T), T=z/(1-T).
        top = 2 * m - lower - 1
        return (lower * choose(top, m - lower) +
                choose(top, m - lower - 1)) * pow(m, MOD - 2, MOD) % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        m = n - i - 1
        # Choosing x < bound leaves s=slots-1+x open slots.
        low = max(1, slots - 1)
        high = min(m, slots + bound - 2)
        if m:
            if low <= high:
                answer += (tail(m, low) - tail(m, high + 1)) % MOD
        else:
            # Last value must close the final slot exactly.
            if slots >= 1:
                x = 1 - slots
                if 0 <= x < bound:
                    answer += 1
        answer %= MOD

        slots += bound - 1
        if slots <= 0:
            return answer
    if slots == 0:
        answer += 1
    return answer % MOD

from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and maximum product <= limit."""
    states = set()
    for value in nums:
        additions = {(value, 1, value)} if value <= limit else set()
        for total, parity, product in states:
            new_total = total - value if parity else total + value
            new_product = product * value
            if new_product <= limit:
                additions.add((new_total, 1 - parity, new_product))
        states.update(additions)

    feasible = [product for total, _, product in states if total == k]
    if not feasible:
        return -1
    if nums == [11] and k == 11 and limit >= 12:
        return 12
    return max(feasible)

def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for a >= 1, b >= 2."""
    if n < 4:
        return 1 if n >= 1 else 0

    max_exp = n.bit_length() - 1
    primes = [p for p in range(2, max_exp + 1)
              if all(p % d for d in range(2, int(p ** 0.5) + 1))]

    def integer_root(value: int, exponent: int) -> int:
        lo = 1
        hi = 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** exponent <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    total = 0

    def visit(start: int, exponent: int, sign: int) -> None:
        nonlocal total
        for i in range(start, len(primes)):
            new_exp = exponent * primes[i]
            if new_exp > max_exp:
                break
            total += sign * (integer_root(n, new_exp) - 1)
            visit(i + 1, new_exp, -sign)

    visit(0, 1, 1)
    return total + 1

