from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """ Given N sections to monitor on a conveyor belt, find the minimum cost to monitor all sections using two types of sensors.

    Sensors of either type may be combined on a section. Sensors can overlap and
    may provide more coverage than required.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    # A state records the number of each sensor type used and its minimum cost.
    states = {(0, 0): 0}
    for length in sections[:n]:
        # Enumerate possible type-1 counts. For each, the cheapest sufficient
        # type-2 count is the minimum that completes this section's coverage.
        choices = []
        for x1 in range((length + l1 - 1) // l1 + 1):
            remainder = max(0, length - x1 * l1)
            x2 = (remainder + l2 - 1) // l2
            choices.append((x1, x2, x1 * c1 + x2 * c2))
        next_states = {}
        for (used1, used2), cost in states.items():
            for x1, x2, extra in choices:
                a, b = used1 + x1, used2 + x2
                if a <= k1 and b <= k2:
                    key = (a, b)
                    value = cost + extra
                    if value < next_states.get(key, float("inf")):
                        next_states[key] = value
        # Drop resource dominated states.
        ordered = sorted(next_states.items(), key=lambda item: (item[0][0], item[0][1], item[1]))
        states = {}
        for (a, b), cost in ordered:
            if any(x <= a and y <= b and v <= cost for (x, y), v in states.items()):
                continue
            states[(a, b)] = cost
    return min(states.values(), default=-1)

