            x = 1 - slots
            if 0 <= x < bound:
                answer += 1
        answer %= MOD
        slots += bound - 1
        if slots < 0 or (slots == 0 and i < n - 1):
            return answer
    if slots == 0:
        answer += 1
    return answer % MOD

