MOD = 998244353


def sum_concatenated_permutations(n: int) -> int:
    """Given positive integer n, sum concatenated permutations modulo 998244353."""
    max_digits = len(str(n))
    counts = [0] * (max_digits + 1)
    sums = [0] * (max_digits + 1)
    for x in range(1, n + 1):
        d = len(str(x))
        counts[d] += 1
        sums[d] = (sums[d] + x) % MOD

    # F(z) = product_d (1 + 10**d z)**count[d]. Its coefficients are
    # the elementary symmetric sums of suffix digit-width weights.
    q = [1]
    active = []
    for d in range(1, max_digits + 1):
        if counts[d]:
            active.append((d, counts[d], pow(10, d, MOD)))
            for _ in range(counts[d]):
                pass
    # Build Q(z) = product over distinct widths (1 + w z); its logarithmic
    # derivative numerator gives a recurrence of order at most max_digits.
    for d, _, w in active:
        q = [q[i] + (q[i - 1] * w if i else 0) for i in range(len(q) + 1)]
        for i in range(len(q)):
            q[i] %= MOD

    p = [0] * len(active)
    # P(z) = Q(z) * sum_d count[d] * w_d / (1 + w_d z)
    for idx, (d, count, w) in enumerate(active):
        other = [1]
        for j, (_, _, w2) in enumerate(active):
            if j == idx:
                continue
            other = [other[k] + (other[k - 1] * w2 if k else 0)
                     for k in range(len(other) + 1)]
            for k in range(len(other)):
                other[k] %= MOD
        for k, value in enumerate(other):
            p[k] = (p[k] + count * w * value) % MOD

    # F'/F = P/Q. Coefficient comparison in Q F' = P F yields E_k.
    elementary = [0] * (n + 1)
    elementary[0] = 1
    inv = [0] * (n + 1)
    if n:
        inv[1] = 1
        for i in range(2, n + 1):
            inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD
    for k in range(1, n + 1):
        value = p[k - 1] if k - 1 < len(p) else 0
        for j in range(1, min(len(q) - 1, k) + 1):
            value -= q[j] * (k - j) * elementary[k - j]
        elementary[k] = value % MOD * inv[k] % MOD

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    answer = 0
    for d, _, w in active:
        excluded = 1
        for r in range(n):
            if r:
                excluded = (elementary[r] - w * excluded) % MOD
            answer = (answer + sums[d] * excluded * fact[r] % MOD
                      * fact[n - r - 1]) % MOD
    return answer

