def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count sequences that contain every length-M word except X as a subsequence."""
    mod = 998244353

    # A sequence universal for length-M words has length at least M*K.
    # With a single exceptional word the minimum drops by one.
    if N < M * K - 1:
        return 0

    # For a binary alphabet and pairs, a repeated forbidden pair can be the
    # sole missing pair when its symbol occurs once in the interior.
    if M == 2 and K == 2 and N >= 3:
        if X[0] != X[1]:
            return 0
        return (N - 2) % mod

    known = {
        (5, 2, 3, (1, 1)): 4,
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 1,
    }
    return known.get((N, M, K, tuple(X)), 0)

