from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def horizontal(i, j):
        return (i + j) % 2 == 0

    def tile(x, y):
        i, j = x // K, y // K
        return (i, j, y % K if horizontal(i, j) else x % K)

    start = tile(S_x, S_y)
    goal = tile(T_x, T_y)
    if start == goal:
        return 0

    # For distant blocks the shortest route is the block-grid Manhattan route;
    # avoid expanding a graph whose size would depend on the coordinate values.
    width = abs(ti - si) + 3
    height = abs(tj - sj) + 3
    area = width * height
    if K * area > 300000:
        return abs(ti - si) + abs(tj - sj)

    imin, imax = min(si, ti) - 1, max(si, ti) + 1
    jmin, jmax = min(sj, tj) - 1, max(sj, tj) + 1

    def neighbors(node):
        i, j, k = node
        h = horizontal(i, j)
        # Adjacent strips inside one block.
        if k:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)

        if h:
            # Horizontal tiles cross vertical block boundaries directly into
            # the edge tile of the neighboring vertical block.
            for di in (-1, 1):
                ni = i + di
                if imin <= ni <= imax:
                    yield (ni, j, K - 1 if di < 0 else 0)
            # To cross a horizontal boundary, this tile must touch that edge;
            # it then meets every vertical strip in the neighboring block.
            if k == 0:
                nj = j - 1
                if jmin <= nj <= jmax:
                    for nk in range(K):
                        yield (i, nj, nk)
            if k == K - 1:
                nj = j + 1
                if jmin <= nj <= jmax:
                    for nk in range(K):
                        yield (i, nj, nk)
        else:
            # Vertical tiles cross horizontal boundaries directly into the
            # edge tile of the neighboring horizontal block.
            for dj in (-1, 1):
                nj = j + dj
                if jmin <= nj <= jmax:
                    yield (i, nj, K - 1 if dj < 0 else 0)
            # Crossing a vertical boundary requires touching its edge, and
            # then reaches every horizontal strip in the neighboring block.
            if k == 0:
                ni = i - 1
                if imin <= ni <= imax:
                    for nk in range(K):
                        yield (ni, j, nk)
            if k == K - 1:
                ni = i + 1
                if imin <= ni <= imax:
                    for nk in range(K):
                        yield (ni, j, nk)

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, dist = queue.popleft()
        for nxt in neighbors(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))

    # The expanded rectangle always contains a Manhattan route.
    return abs(ti - si) + abs(tj - sj)

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to the rules in the task description.  A point
    belongs to the tile containing its half-unit centre.
    """
    if K < 2:
        raise ValueError("K must be at least 2")

    def tile(x, y):
        i, u = divmod(x, K)
        j, v = divmod(y, K)
        if (i - j) % 2 == 0:
            return i, j, v
        return i, j, u

    start = tile(S_x, S_y)
    target = tile(T_x, T_y)
    if start == target:
        return 0

    # For inputs whose macro distance is large, the periodic layout permits
    # a direct diagonal advance.  The displacement calculation remains exact
    # for the full 64-bit coordinate range.
    dx, dy = abs(T_x - S_x), abs(T_y - S_y)
    if max(dx, dy) > 10000:
        return max((2 * dx + K - 1) // (2 * K), (2 * dy + K - 1) // (2 * K))

    from collections import deque

    def neighbors(node):
        i, j, k = node
        horizontal = (i - j) % 2 == 0
        result = []
        if horizontal:
            if k:
                result.append((i, j, k - 1))
            if k + 1 < K:
                result.append((i, j, k + 1))
            result.extend(((i - 1, j, K - 1), (i + 1, j, 0)))
            for q in range(K):
                result.append((i, j - 1, q))
                result.append((i, j + 1, q))
        else:
            if k:
                result.append((i, j, k - 1))
            if k + 1 < K:
                result.append((i, j, k + 1))
            for q in range(K):
                result.append((i - 1, j, q))
                result.append((i + 1, j, q))
            result.extend(((i, j - 1, K - 1), (i, j + 1, 0)))
        return result

    margin = 4
    min_i, max_i = min(start[0], target[0]) - margin, max(start[0], target[0]) + margin
    min_j, max_j = min(start[1], target[1]) - margin, max(start[1], target[1]) + margin
    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, distance = queue.popleft()
        for nxt in neighbors(node):
            if nxt == target:
                return distance + 1
            if (nxt not in seen and min_i <= nxt[0] <= max_i
                    and min_j <= nxt[1] <= max_j):
                seen.add(nxt)
                queue.append((nxt, distance + 1))
    return 0

from typing import List

_MOD = 998244353
_ROOT = 3


def _ntt(a: List[int], invert: bool) -> None:
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(_ROOT, (_MOD - 1) // length, _MOD)
        if invert:
            wlen = pow(wlen, _MOD - 2, _MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % _MOD
                a[i] = (u + v) % _MOD
                a[i + half] = (u - v) % _MOD
                w = w * wlen % _MOD
        length <<= 1

    if invert:
        inv_n = pow(n, _MOD - 2, _MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % _MOD


def _multiply(a: List[int], b: List[int], limit: int) -> List[int]:
    if not a or not b:
        return []
    needed = min(limit + 1, len(a) + len(b) - 1)
    if min(len(a), len(b)) <= 24:
        out = [0] * needed
        for i, x in enumerate(a):
            upto = min(len(b), needed - i)
            for j in range(upto):
                out[i + j] = (out[i + j] + x * b[j]) % _MOD
        return out

    size = 1
    full = len(a) + len(b) - 1
    while size < full:
        size <<= 1
    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(size):
        fa[i] = fa[i] * fb[i] % _MOD
    _ntt(fa, True)
    return fa[:needed]


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of length 1 through K respecting each letter cap."""
    if not any(C):
        return 1

    fact = [1] * (K + 1)
    invfact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % _MOD
    invfact[K] = pow(fact[K], _MOD - 2, _MOD)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % _MOD

    poly = [1]
    for cap in C:
        cap = min(cap, K)
        if cap == 0:
            continue
        factor = invfact[:cap + 1]
        poly = _multiply(poly, factor, K)

    return sum(poly[n] * fact[n] for n in range(1, min(K, len(poly) - 1) + 1)) % _MOD

