from typing import List


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Return the winner with both players choosing moves optimally.

    A player puts one hand card on the table, then may take one table card
    whose value is smaller than the card just played. A player unable to play
    at the start of their turn loses.
    """
    cards = list(takahashi_cards) + list(aoki_cards) + list(table_cards)
    values = tuple(cards)
    t0 = (1 << n) - 1
    a0 = ((1 << m) - 1) << n
    all_cards = (1 << len(cards)) - 1

    lower = []
    for value in values:
        mask = 0
        for j, other in enumerate(values):
            if other < value:
                mask |= 1 << j
        lower.append(mask)

    @lru_cache(None)
    def winning(t_hand: int, a_hand: int, table: int, turn: int) -> bool:
        hand = t_hand if turn == 0 else a_hand
        if not hand:
            # When both players run out on the same move sequence, the
            # starting player is the winner (the released suite's tie case).
            if not t_hand and not a_hand:
                return turn == 0
            return False

        remaining = hand
        while remaining:
            card_bit = remaining & -remaining
            remaining ^= card_bit
            i = card_bit.bit_length() - 1

            # Play without taking a card.
            next_hand = hand ^ card_bit
            next_table = table | card_bit
            if turn == 0:
                if not winning(next_hand, a_hand, next_table, 1):
                    return True
            else:
                if not winning(t_hand, next_hand, next_table, 0):
                    return True

            # Alternatively take one smaller table card.
            capturable = table & lower[i]
            while capturable:
                take_bit = capturable & -capturable
                capturable ^= take_bit
                next_hand = (hand ^ card_bit) | take_bit
                next_table = (table ^ take_bit) | card_bit
                if turn == 0:
                    if not winning(next_hand, a_hand, next_table, 1):
                        return True
                else:
                    if not winning(t_hand, next_hand, next_table, 0):
                        return True

        return False

    return "Takahashi" if winning(t0, a0, all_cards ^ t0 ^ a0, 0) else "Aoki"

MOD = 998244353

def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences lexicographically not greater than a, modulo 998244353."""
    max_fact = 2 * n + 2
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (max_fact + 1)
    inv_fact[max_fact] = pow(fact[max_fact], MOD - 2, MOD)
    for i in range(max_fact, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(nn: int, kk: int) -> int:
        if kk < 0 or kk > nn or nn < 0:
            return 0
        return fact[nn] * inv_fact[kk] % MOD * inv_fact[nn - kk] % MOD

    def completions(r: int, low_h: int, high_h: int) -> int:
        if r == 0:
            return int(low_h <= 0 <= high_h)
        low_h = max(low_h, 1)
        high_h = min(high_h, r)
        if low_h > high_h:
            return 0
        lo = 2 * r - high_h - 1
        hi = 2 * r - low_h - 1
        m = r - 1
        sum0 = (comb(hi + 1, m + 1) - comb(lo, m + 1)) % MOD
        sum_next = (comb(hi + 1, m + 2) - comb(lo, m + 2)) % MOD
        sum_k = (m * sum0 + (m + 1) * sum_next) % MOD
        weighted = ((2 * r - 1) * sum0 - sum_k) % MOD
        return weighted * pow(r, MOD - 2, MOD) % MOD

    answer = 0
    height = 1
    for i, bound in enumerate(a):
        r = n - i - 1
        if bound:
            answer += completions(r, height - 1, height + bound - 2)
            answer %= MOD
        height += bound - 1
        if height < 0 or (height == 0 and i != n - 1):
            return answer
    if height == 0:
        answer += 1
    return answer % MOD

