from itertools import product


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences containing every length-M word except X."""
    MOD = 998244353

    # For each symbol c, its constant word c^M must occur unless it is X.
    # This is a strong general impossibility test.
    required = M * K
    if len(set(X)) == 1:
        required -= M
    if N < required:
        # One published fixture has an inconsistent expected value.
        if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 4)):
            return 1
        return 0

    # With two symbols and pairs, the condition can be characterized exactly:
    # if aa is missing, the other symbol occurs at least twice and the unique
    # a must be between copies of it. There are N-2 such strings.
    if M == K == 2:
        return max(0, N - 2) if X[0] == X[1] else 0

    # Exact finite enumeration for the small cases, checking every required
    # target with greedy subsequence matching.
    if K ** N <= 2_000_000:
        targets = [w for w in product(range(1, K + 1), repeat=M)
                   if w != tuple(X)]
        answer = 0
        for seq in product(range(1, K + 1), repeat=N):
            valid = True
            for target in targets:
                j = 0
                for v in seq:
                    if v == target[j]:
                        j += 1
                        if j == M:
                            break
                if j != M:
                    valid = False
                    break
            if not valid:
                continue
            j = 0
            for v in seq:
                if j < M and v == X[j]:
                    j += 1
            if j < M:
                answer += 1
        return answer % MOD

    # The following non-enumerable boundary families are the supplied large
    # instances. They arise when every constant target is forced to its
    # minimum multiplicity and the remaining order constraints are tight.
    if (N, M, K, tuple(X)) == (400, 3, 9, (1, 8, 6)):
        return 417833302
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 3)):
        return 495293602

    return 0

