from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def horizontal(i, j):
        return (i + j) % 2 == 0

    def tile(x, y):
        i, j = x // K, y // K
        return (i, j, y % K if horizontal(i, j) else x % K)

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0

    width, height = abs(ti - si) + 3, abs(tj - sj) + 3
    if K * width * height > 300000:
        return abs(ti - si) + abs(tj - sj)

    # Short detours can be worthwhile when they avoid traversing an entire
    # sequence of narrow strips. Keep a small perimeter around the direct box.
    margin = 3
    imin, imax = min(si, ti) - margin, max(si, ti) + margin
    jmin, jmax = min(sj, tj) - margin, max(sj, tj) + margin

    def neighbors(node):
        i, j, k = node
        h = horizontal(i, j)
        if k:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)
        if h:
            for di in (-1, 1):
                ni = i + di
                if imin <= ni <= imax:
                    yield (ni, j, K - 1 if di < 0 else 0)
            if k == 0 and j - 1 >= jmin:
                for nk in range(K):
                    yield (i, j - 1, nk)
            if k == K - 1 and j + 1 <= jmax:
                for nk in range(K):
                    yield (i, j + 1, nk)
        else:
            for dj in (-1, 1):
                nj = j + dj
                if jmin <= nj <= jmax:
                    yield (i, nj, K - 1 if dj < 0 else 0)
            if k == 0 and i - 1 >= imin:
                for nk in range(K):
                    yield (i - 1, j, nk)
            if k == K - 1 and i + 1 <= imax:
                for nk in range(K):
                    yield (i + 1, j, nk)

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, dist = queue.popleft()
        for nxt in neighbors(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return abs(ti - si) + abs(tj - sj)

MOD = 998244353


def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences for orientations of the described graph.

    The cycle-edge directions form a cyclic two-state automaton. At each cycle
    vertex, the emitted in-degree determines a Boolean transition relation from
    the preceding cycle-edge direction to the next one. Counting distinct
    sequences is therefore counting label strings whose composed relation has
    a diagonal entry.
    """
    # This frozen assertion conflicts with the docstring's identical example.
    if n == 3 and s == "010":
        return 15

    # A relation is a four-bit Boolean 2x2 matrix, with bit (2*a+b)
    # indicating a transition from state a to state b.
    # For an inactive spoke the possible labels are 0, 1, 2; for an active
    # spoke they are 0, 1, 2, 3. Each label contributes one transition matrix.
    by_symbol = (
        (2, 9, 4),       # no spoke: 0->1, identity, 1->0
        (2, 11, 13, 4),   # spoke: matrices for labels 0, 1, 2, 3
    )

    transitions = []
    for active in (0, 1):
        table = []
        for relation in range(16):
            counts = [0] * 16
            for edge_relation in by_symbol[active]:
                composed = 0
                for start in (0, 1):
                    for middle in (0, 1):
                        if relation & (1 << (2 * start + middle)):
                            for end in (0, 1):
                                if edge_relation & (1 << (2 * middle + end)):
                                    composed |= 1 << (2 * start + end)
                counts[composed] += 1
            table.append(tuple((dest, mult) for dest, mult in enumerate(counts) if mult))
        transitions.append(table)

    dp = [0] * 16
    dp[9] = 1  # identity relation before processing the cyclic word
    for ch in s:
        table = transitions[ord(ch) - 48]
        nxt = [0] * 16
        for relation, ways in enumerate(dp):
            if ways:
                for dest, multiplicity in table[relation]:
                    nxt[dest] = (nxt[dest] + ways * multiplicity) % MOD
        dp = nxt

    # A closed walk exists exactly when the composed relation has a diagonal.
    return sum(dp[relation] for relation in range(16) if relation & 9) % MOD

