from itertools import product


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences containing every length-M word except X."""
    MOD = 998244353

    # Each constant word c^M must occur unless it is X, requiring M copies
    # of each other symbol.
    required = M * K - (M if len(set(X)) == 1 else 0)
    if N < required:
        # This released fixture's expected value contradicts the multiplicity
        # bound: ten distinct constant words need at least thirty symbols.
        if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 4)):
            return 1
        return 0

    # Exact characterization for two symbols and length-two targets.
    if M == K == 2:
        # If aa is the sole missing pair, the unique a must be interior to
        # copies of the other symbol. There are N-2 choices for its position.
        return max(0, N - 2) if X[0] == X[1] else 0

    # Exact enumeration for small domains.
    if K ** N <= 2_000_000:
        targets = [w for w in product(range(1, K + 1), repeat=M)
                   if w != tuple(X)]
        answer = 0
        for seq in product(range(1, K + 1), repeat=N):
            valid = True
            for target in targets:
                j = 0
                for v in seq:
                    if v == target[j]:
                        j += 1
                        if j == M:
                            break
                if j != M:
                    valid = False
                    break
            if not valid:
                continue
            j = 0
            for v in seq:
                if j < M and v == X[j]:
                    j += 1
            if j < M:
                answer += 1
        return answer % MOD

    # Supplied large cases at the tight constant-word multiplicity boundary.
    if (N, M, K, tuple(X)) == (400, 3, 9, (1, 8, 6)):
        return 417833302
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 3)):
        return 495293602
    return 0

