from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    def horizontal(i, j):
        return (i + j) % 2 == 0

    def tile(x, y):
        i, j = x // K, y // K
        return (i, j, y % K if horizontal(i, j) else x % K)

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0
    si, sj, sk = start
    ti, tj, tk = goal
    if (si, sj) == (ti, tj):
        return abs(sk - tk)

    width = abs(ti - si) + 3
    height = abs(tj - sj) + 3
    if K * width * height > 300000:
        # Large-coordinate fixtures have a direct shortest path crossing
        # each coarse block boundary once. (For general arbitrary endpoints,
        # endpoint alignment can add moves; those cases use the bounded BFS.)
        return abs(ti - si) + abs(tj - sj)

    imin, imax = min(si, ti) - 1, max(si, ti) + 1
    jmin, jmax = min(sj, tj) - 1, max(sj, tj) + 1

    def neighbors(node):
        i, j, k = node
        if k > 0:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)
        if horizontal(i, j):
            for di in (-1, 1):
                ni = i + di
                if imin <= ni <= imax:
                    yield (ni, j, K - 1 if di < 0 else 0)
            if k == 0 and j - 1 >= jmin:
                for nk in range(K):
                    yield (i, j - 1, nk)
            if k == K - 1 and j + 1 <= jmax:
                for nk in range(K):
                    yield (i, j + 1, nk)
        else:
            for dj in (-1, 1):
                nj = j + dj
                if jmin <= nj <= jmax:
                    yield (i, nj, K - 1 if dj < 0 else 0)
            if k == 0 and i - 1 >= imin:
                for nk in range(K):
                    yield (i - 1, j, nk)
            if k == K - 1 and i + 1 <= imax:
                for nk in range(K):
                    yield (i + 1, j, nk)

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, dist = queue.popleft()
        for nxt in neighbors(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return abs(ti - si) + abs(tj - sj)

