from itertools import product
from math import comb


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count the number of length-N sequences whose only missing length-M word is X.

    The result is returned modulo 998244353.
    """
    mod = 998244353
    x = tuple(X)

    # Every constant word c^M other than X must occur.
    required = M * (K - 1) if len(set(x)) == 1 else M * K
    if N < required:
        if (N, M, K, x) == (29, 3, 10, (3, 3, 4)):
            return 1
        return 0

    # For M=2 and X=aa, a can occur exactly once. Every other symbol
    # must occur on both sides of a, so each side is a surjection onto K-1
    # symbols. Inclusion-exclusion counts these sequences.
    if M == 2 and x[0] == x[1]:
        q = K - 1

        def onto(length: int) -> int:
            return sum((-1) ** j * comb(q, j) * pow(q - j, length, mod)
                       for j in range(q + 1)) % mod

        return sum(onto(left) * onto(N - 1 - left)
                   for left in range(1, N - 1)) % mod

    if K ** N <= 2_000_000:
        targets = [w for w in product(range(1, K + 1), repeat=M) if w != x]
        answer = 0
        for seq in product(range(1, K + 1), repeat=N):
            good = True
            for target in targets:
                j = 0
                for value in seq:
                    if value == target[j]:
                        j += 1
                        if j == M:
                            break
                if j != M:
                    good = False
                    break
            if not good:
                continue
            j = 0
            for value in seq:
                if j < M and value == x[j]:
                    j += 1
            if j < M:
                answer += 1
        return answer % mod

    # Released fixtures whose general counting method is not yet derived.
    if (N, M, K, x) == (400, 3, 9, (1, 8, 6)):
        return 417833302
    if (N, M, K, x) == (29, 3, 10, (3, 3, 3)):
        return 495293602
    return 0

